"""Synthetic media fixtures (generated by FFmpeg, no private material). Clearly named `fixture-*`."""

from __future__ import annotations

import os
from pathlib import Path

from .media import run_tool, tool


def generate(out_dir: Path, seconds: int = 6) -> dict[str, Path]:
    out_dir.mkdir(parents=True, exist_ok=True)
    ffmpeg = [tool("ffmpeg"), "-nostdin", "-hide_banner", "-loglevel", "error", "-y"]
    files = {
        "clase": out_dir / "fixture-clase.mp4",
        "cortinilla": out_dir / "fixture-cortinilla.mp4",
        "slide": out_dir / "fixture-slide.png",
        "voz": out_dir / "fixture-tono.wav",
    }
    run_tool(
        [
            *ffmpeg,
            "-f",
            "lavfi",
            "-i",
            f"testsrc2=s=1280x720:r=30:d={seconds}",
            "-f",
            "lavfi",
            "-i",
            f"sine=frequency=440:sample_rate=48000:duration={seconds}",
            "-c:v",
            "libx264",
            "-preset",
            "ultrafast",
            "-pix_fmt",
            "yuv420p",
            "-c:a",
            "aac",
            "-shortest",
            str(files["clase"]),
        ]
    )
    run_tool(
        [
            *ffmpeg,
            "-f",
            "lavfi",
            "-i",
            "smptehdbars=s=1280x720:r=30:d=2",
            "-f",
            "lavfi",
            "-i",
            "sine=frequency=880:sample_rate=48000:duration=2",
            "-c:v",
            "libx264",
            "-preset",
            "ultrafast",
            "-pix_fmt",
            "yuv420p",
            "-c:a",
            "aac",
            "-shortest",
            str(files["cortinilla"]),
        ]
    )
    run_tool([*ffmpeg, "-f", "lavfi", "-i", "color=c=navy:s=1280x720", "-frames:v", "1", str(files["slide"])])
    run_tool(
        [
            *ffmpeg,
            "-f",
            "lavfi",
            "-i",
            f"sine=frequency=330:sample_rate=48000:duration={seconds}",
            str(files["voz"]),
        ]
    )
    return files


def corrupt_file(path: Path) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(b"\x00\x00\x00\x18ftypmp42" + os.urandom(4096))
    return path
